package com.gatecraft.game;

import android.content.Context;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.Paint;
import android.graphics.RectF;
import java.util.Random;

final class MetalFighterView extends BaseArcadeView {
  private final ArcadeFx fx=new ArcadeFx();private final Random rnd=new Random(33);
  private float x=210,ex=735,vx,evx,y,ey,vy,evy,ai,atk,eAtk,specialCd,hitFlash,shake,roundClock=60,comboTimer,special=35;
  private int hp=100,ehp=100,score,round=1,wins,losses,combo,pAttack,eAttack,facing=1,eFacing=-1;
  private boolean left,right,block,punch,kick,arc,jump,jumpLatch,ground=true,eGround=true;
  private final RectF bL=new RectF(18,432,110,524),bR=new RectF(116,432,208,524),bJ=new RectF(214,432,316,524),bP=new RectF(574,426,666,524),bK=new RectF(671,426,763,524),bB=new RectF(768,426,860,524),bA=new RectF(865,420,958,524);
  MetalFighterView(Context c,GateCraftGame o){super(c,o);}
  @Override public int score(){return score;}@Override public int level(){return round;}@Override public int lives(){return Math.max(1,2-losses);}@Override public void shutdown(){super.shutdown();fx.clear();}
  @Override public void restart(){x=210;ex=735;y=ey=0;vy=evy=0;hp=ehp=100;vx=evx=0;specialCd=hitFlash=shake=atk=eAtk=0;left=right=block=punch=kick=arc=jump=false;ground=eGround=true;roundClock=60;combo=0;comboTimer=0;special=Math.max(20,special);invalidate();}

  @Override void updateGame(float dt){fx.update(dt);specialCd=Math.max(0,specialCd-dt);hitFlash=Math.max(0,hitFlash-dt);shake=Math.max(0,shake-dt);atk=Math.max(0,atk-dt);eAtk=Math.max(0,eAtk-dt);comboTimer=Math.max(0,comboTimer-dt);if(comboTimer<=0)combo=0;roundClock=Math.max(0,roundClock-dt);special=Math.min(100,special+dt*4);
    float sp=300;if(left)vx=-sp;else if(right)vx=sp;else vx*=Math.pow(.0008,dt);if(jump&&!jumpLatch&&ground){vy=-565;ground=false;jumpLatch=true;fx.dust(x,385,8,Color.rgb(92,88,82));}if(!jump)jumpLatch=false;if(!ground){vy+=1360*dt;y+=vy*dt;if(y>=0){y=0;vy=0;ground=true;fx.dust(x,388,8,Color.rgb(98,93,84));}}x+=vx*dt;x=Math.max(62,Math.min(898,x));facing=x<=ex?1:-1;eFacing=-facing;
    ai-=dt;if(ai<=0){ai=.16f+rnd.nextFloat()*.24f;float d=x-ex,ad=Math.abs(d);if(ad>155)evx=(d>0?1:-1)*(165+rnd.nextFloat()*80);else{evx*=.3f;float r=rnd.nextFloat();if(r<.48f)enemyStrike(rnd.nextFloat()<.27f?2:1);else if(r<.60f&&eGround){evy=-500;eGround=false;}}}if(!eGround){evy+=1360*dt;ey+=evy*dt;if(ey>=0){ey=0;evy=0;eGround=true;}}ex+=evx*dt;ex=Math.max(62,Math.min(898,ex));evx*=Math.pow(.05,dt);if(Math.abs(x-ex)<74&&Math.abs(y-ey)<65){float mid=(x+ex)/2;if(x<ex){x=Math.min(x,mid-38);ex=Math.max(ex,mid+38);}else{x=Math.max(x,mid+38);ex=Math.min(ex,mid-38);}}
    if(punch){punch=false;strike(10,102,1,.24f);}if(kick){kick=false;strike(16,126,2,.33f);}if(arc){arc=false;if(specialCd<=0&&special>=50){special-=50;specialCd=2.2f;strike(28,245,3,.46f);fx.sparks(x+facing*76,318+y,28,Color.rgb(100,202,255));}}if(roundClock<=0){if(hp>=ehp)ehp=0;else hp=0;}if(ehp<=0)win();else if(hp<=0)lose();}
  private void strike(int dmg,float range,int kind,float duration){if(atk>0)return;pAttack=kind;atk=duration;if(Math.abs(x-ex)<=range&&Math.abs(y-ey)<82){int dealt=dmg+(combo>=2?3:0);ehp-=dealt;ex+=facing*(kind==2?28:18);hitFlash=.10f;shake=kind==3?.20f:.09f;combo++;comboTimer=.9f;special=Math.min(100,special+9);score+=dealt*(5+combo);owner.reportScore(score);fx.sparks(ex-facing*22,316+ey,kind==3?26:11,kind==3?Color.rgb(105,205,255):Color.rgb(255,192,70));}}
  private void enemyStrike(int kind){if(eAtk>0)return;eAttack=kind;eAtk=kind==2?.38f:.27f;if(Math.abs(x-ex)<(kind==2?125:102)&&Math.abs(y-ey)<82){int d=kind==2?17:12;if(block){d=4;special=Math.min(100,special+4);fx.sparks(x-facing*28,320+y,8,Color.rgb(190,210,230));}hp-=d;x-=facing*(block?5:18);hitFlash=.10f;shake=.08f;combo=0;fx.sparks(x+facing*22,317+y,9,Color.rgb(255,145,55));}}
  private void win(){score+=1200+Math.max(0,(int)roundClock)*10;wins++;round++;owner.reportGameComplete(score);fx.sparks(ex,280,40,Color.rgb(255,218,75));restart();}
  private void lose(){losses++;owner.reportGameOver(score);score=Math.max(0,score-250);restart();}

  @Override void drawGame(Canvas c){float sh=shake>0?(float)Math.sin(System.currentTimeMillis()*.08)*7:0;c.save();c.translate(sh,0);fill(c,Color.rgb(26,17,31),0,0,960,540);fill(c,Color.rgb(76,42,91),0,74,960,238);for(int yy=82;yy<238;yy+=18)fill(c,(yy/18)%2==0?Color.rgb(88,50,102):Color.rgb(66,38,82),0,yy,960,yy+8);for(int bx=-30;bx<1000;bx+=145){fill(c,Color.rgb(39,34,37),bx,190,bx+76,392);fill(c,Color.rgb(102,70,43),bx+8,205,bx+19,392);fill(c,Color.rgb(13,15,19),bx+29,246,bx+64,392);for(int yy=260;yy<370;yy+=31)fill(c,Color.rgb(205,128,42),bx+37,yy,bx+52,yy+8);}line(c,Color.rgb(205,148,57),8,30,137,575,137);line(c,Color.rgb(205,148,57),7,575,137,805,214);line(c,Color.rgb(205,148,57),5,300,137,300,218);fill(c,Color.rgb(65,37,30),427,284,540,390);fill(c,Color.rgb(232,84,29),446,305,521,365);fill(c,Color.rgb(255,199,57),459,315,508,351);for(int i=0;i<17;i++){float sx=475+(i%6)*12,sy=297-(i*19%66)+(float)Math.sin(i+System.currentTimeMillis()*.01)*4;fill(c,i%2==0?Color.rgb(255,216,73):Color.rgb(239,104,35),sx,sy,sx+3,sy+6);}fill(c,Color.rgb(42,50,58),0,358,960,540);for(int yy=360;yy<540;yy+=23)line(c,Color.rgb(25,31,37),2,0,yy,960,yy);for(int bx=-120;bx<1080;bx+=56)line(c,Color.rgb(67,77,84),2,bx,358,bx+155,540);line(c,Color.rgb(182,135,49),4,0,394,960,394);fighter(c,x,389+y,false,facing,pAttack,atk,block);fighter(c,ex,389+ey,true,eFacing,eAttack,eAtk,false);fx.draw(c,p);if(hitFlash>0)fill(c,Color.argb(55,255,235,175),0,74,960,410);c.restore();
    fill(c,Color.rgb(7,7,11),0,0,960,77);text(c,"METAL FIGHTER",480,30,27,Color.rgb(248,211,80),Paint.Align.CENTER,true);text(c,t("LAKATOS SZAKI","METALWORKER","METALLBAUER","HERRERO","MÉTALLIER","金属工","FABBRO","SERRALHEIRO","ŚLUSARZ","METAALBEWERKER","LĂCĂTUȘ","СЛЕСАРЬ"),18,61,13,Color.WHITE,Paint.Align.LEFT,true);text(c,t("KÓKLER KONTÁR","HACK RIVAL","PFUSCHER","CHAPUCERO","BRICOLEUR","劣质工","PASTICCIONE","GAMBIARRA","PARTACZ","BEUNHAAS","CÂRPACI","ХАЛТУРЩИК"),942,61,13,Color.WHITE,Paint.Align.RIGHT,true);bar(c,18,9,hp,Color.rgb(57,194,75),false);bar(c,662,9,ehp,Color.rgb(211,59,46),true);text(c,"R"+round+"  "+Math.max(0,(int)roundClock),480,60,18,Color.WHITE,Paint.Align.CENTER,true);fill(c,Color.rgb(31,30,37),345,11,615,19);fill(c,Color.rgb(112,65,164),347,13,347+266*special/100f,17);text(c,"ARC "+(int)special+"%",480,18,10,Color.rgb(214,190,255),Paint.Align.CENTER,true);if(combo>=2)text(c,"COMBO x"+combo,480,96,22,Color.rgb(255,201,63),Paint.Align.CENTER,true);
    arcadeButton(c,bL,"◀",Color.rgb(45,99,158),left);arcadeButton(c,bR,"▶",Color.rgb(45,99,158),right);arcadeButton(c,bJ,"▲",Color.rgb(45,99,158),jump);arcadeButton(c,bP,t("ÜT","HIT","HIEB","GOLPE","COUP","拳","COLPO","SOCO","CIOS","SLAG","LOV","УДАР"),Color.rgb(169,58,43),touched(bP));arcadeButton(c,bK,t("RÚG","KICK","TRITT","PATADA","PIED","踢","CALCIO","CHUTE","KOP","TRAP","PICIOR","ПИНОК"),Color.rgb(178,91,35),touched(bK));arcadeButton(c,bB,t("VÉD","BLOCK","BLOCK","BLOQ","BLOC","防御","PARA","DEF","BLOK","BLOK","BLOC","БЛОК"),Color.rgb(54,101,139),block);arcadeButton(c,bA,(special>=50&&specialCd<=0)?t("ÍV","ARC","LICHT","ARCO","ARC","电弧","ARCO","ARCO","ŁUK","BOOG","ARC","ДУГА"):"…",Color.rgb(119,65,165),touched(bA));}
  private void bar(Canvas c,float bx,float by,int v,int col,boolean rev){float w=280;fill(c,Color.rgb(40,35,31),bx,by,bx+w,by+19);float f=Math.max(0,v)/100f;if(rev)fill(c,col,bx+w-w*f+2,by+2,bx+w-2,by+17);else fill(c,col,bx+2,by+2,bx+2+(w-4)*f,by+17);stroke(c,Color.rgb(234,220,170),2,bx,by,bx+w,by+19);}
  private void fighter(Canvas c,float px,float gy,boolean enemy,int face,int attack,float timer,boolean def){int state=def?3:timer>0?2:Math.abs(enemy?evx:vx)>40?1:0;float phase=(System.currentTimeMillis()%1000)/1000f;SpriteKit.worker(c,p,px,gy,1.85f,face,state,phase,enemy);if(timer>0){float d=face>=0?1:-1;if(attack==1)fill(c,enemy?Color.rgb(196,145,101):Color.rgb(224,174,113),px+d*18,gy-85,px+d*54,gy-69);else if(attack==2)line(c,Color.rgb(47,49,55),12,px+d*8,gy-36,px+d*58,gy-53);else if(attack==3){line(c,Color.rgb(94,194,255),12,px+d*32,gy-88,px+d*142,gy-111);line(c,Color.WHITE,3,px+d*36,gy-88,px+d*142,gy-111);}}}

  private void sync(){left=touched(bL);right=touched(bR);jump=touched(bJ);block=touched(bB);}
  @Override void onGameDown(float tx,float ty){sync();if(in(bP,tx,ty))punch=true;if(in(bK,tx,ty))kick=true;if(in(bA,tx,ty))arc=true;}
  @Override void onGameMove(float tx,float ty){sync();}
  @Override void onGameUp(float tx,float ty){sync();}
}
